 36	
 37	  /* 5b. Thong chuoi DSI va dua panel ra khoi reset */
 38	  __HAL_RCC_GPIOH_CLK_ENABLE();
 39	  GPIO_InitTypeDef gpio_xres = {0};
 40	  gpio_xres.Pin = GPIO_PIN_7;
 41	  gpio_xres.Mode = GPIO_MODE_OUTPUT_PP;
 42	  gpio_xres.Pull = GPIO_PULLUP;
 43	  gpio_xres.Speed = GPIO_SPEED_HIGH;
 44	  HAL_GPIO_Init(GPIOH, &gpio_xres);
 45	  HAL_GPIO_WritePin(GPIOH, GPIO_PIN_7, GPIO_PIN_SET);
 46	
 47	  /* Xoa SHTDN (bit 3) va bat DSIEN (bit 0) tren DSI Wrapper */
 48	  DSI->WCR &= ~DSI_WCR_SHTDN;
 49	  DSI->WCR |= DSI_WCR_DSIEN;
 50	
 51	/* 5c. Gui truc tiep cac lenh khoi tao OTM8009A qua DSI DCS Short Write */
 52	  extern DSI_HandleTypeDef hdsi_eval;
 53	  extern int32_t DSI_IO_ReadCmd(uint32_t Reg, uint8_t *pData, uint32_t Size);
 54	
 55	  /* 0x11: Sleep Out */
 56	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x11, 0x00);
 57	  HAL_Delay(120);
 58	  /* 0x51: WRDISBV - dat do sang toi da (0xFF) */
 59	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x51, 0xFF);
 60	  /* 0x53: WRCTRLD - bat BCTRL (0x2C: BCTRL=1, DD=1, BL=1) */
 61	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P1, 0x53, 0x2C);
 62	  /* 0x29: Display On */
 63	  HAL_DSI_ShortWrite(&hdsi_eval, 0, DSI_DCS_SHORT_PKT_WRITE_P0, 0x29, 0x00);
 64	  HAL_Delay(50);
 65	
 66	  /* Doc cac thanh ghi trang thai DCS cua panel */
 67	  DSI_IO_ReadCmd(0xDA, (uint8_t *)&g_panel_dcs[0], 1); /* ID1 */
 68	  DSI_IO_ReadCmd(0x0A, (uint8_t *)&g_panel_dcs[1], 1); /* Power Mode */
 69	  DSI_IO_ReadCmd(0x0B, (uint8_t *)&g_panel_dcs[2], 1); /* MADCTL */
 70	  DSI_IO_ReadCmd(0x0C, (uint8_t *)&g_panel_dcs[3], 1); /* COLMOD */
 71	  DSI_IO_ReadCmd(0x52, (uint8_t *)&g_panel_dcs[4], 1); /* Brightness */
 72	  DSI_IO_ReadCmd(0x54, (uint8_t *)&g_panel_dcs[5], 1); /* CTRL Display */
 73	  DSI_IO_ReadCmd(0x0F, (uint8_t *)&g_panel_dcs[6], 1); /* Self-Diagnostic */
 74	  DSI_IO_ReadCmd(0x0D, (uint8_t *)&g_panel_dcs[7], 1); /* Image Mode */
 75	
 76	  /* 6. Xoa man hinh ve mau trang */
 77	  BSP_LCD_Clear(LCD_COLOR_WHITE);
 78	
 79	  uint32_t lcd_w = BSP_LCD_GetXSize();
 80	
 81	  /* 7. Ve Logo PTIT (240x240) ra giua man hinh */
 82	  uint32_t logo_x = (lcd_w > LOGO_PTIT_WIDTH) ? ((lcd_w - LOGO_PTIT_WIDTH) / 2) : 0;
 83	  uint32_t logo_y = 30;
 84	  DrawLogo(logo_x, logo_y);
 85	
 86	  /* 8. Hien thi 4 dong chu thong tin theo yeu cau */
 87	  BSP_LCD_SetBackColor(LCD_COLOR_WHITE);
 88	  BSP_LCD_SetTextColor(LCD_COLOR_DARKBLUE);
 89	  BSP_LCD_SetFont(&Font20);
 90	
 91	  /* Dong 1: EIDE v3 — IDE nhung co tac tu dong tac gia */
 92	  BSP_LCD_DisplayStringAt(0, 290, (uint8_t *)"EIDE v3 - IDE nhung co tac tu dong tac gia", CENTER_MODE);
 93	
 94	  BSP_LCD_SetTextColor(LCD_COLOR_BLACK);
 95	  BSP_LCD_SetFont(&Font16);
 96	
 97	  /* Dong 2: Hoc vien: Vu Tri Cong */
 98	  BSP_LCD_DisplayStringAt(0, 330, (uint8_t *)"Hoc vien: Vu Tri Cong", CENTER_MODE);
 99	
